{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The load balancer listener is configured to use HTTP on port 80, which transmits data in cleartext and exposes it to interception or modification. It should be changed to HTTPS with a valid SSL certificate."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "Ensure that load balancer is using at least TLS 1.2",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "Since the listener is currently HTTP, it does not enforce any TLS version. When switching to HTTPS, an explicit security policy enforcing TLS 1.2 or higher must be defined to prevent downgrade attacks."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_certificate_arn = var.ssl_certificate_arn # User must provide this variable or hardcode ARN\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}\n\nvariable \"ssl_certificate_arn\" {\n  description = \"ARN of the ACM certificate for the HTTPS listener\"\n  type        = string\n}",
  "fix_summary": "Changed the listener protocol from HTTP to HTTPS and updated the port to 443. Added an `ssl_certificate_arn` attribute (referencing a new variable) to enable encryption. Note: In a production environment, you should also explicitly set `ssl_policy` to something like 'ELBSecurityPolicy-TLS-1-2-2017-01' if the default provider policy is insufficient, but adding the certificate is the primary remediation for CKV_AWS_2/103 in this context."
}
